-- Seed the SAMPLE marketplace catalogue (79 items) into public.products.
-- Mirrors `catalog` in lib/features/market/market_models.dart; test/market_seed_sync_test.dart
-- fails if the two drift. SAMPLE only: no real brands, prices or products. Medicines and
-- supplements are consult_only, so market_cart_guard rejects them. Idempotent.
on conflict (id) do update set
  dimension = excluded.dimension,
  category = excluded.category,
  name = excluded.name,
  blurb = excluded.blurb,
  price_sample = excluded.price_sample,
  consult_only = excluded.consult_only;
